  }

  return (
    <div className="grid grid-cols-3 gap-4">
      {products.map(p => <ProductCard key={p.id} product={p} />)}
    </div>
  );
}
```

## Pattern 2: Container-Based Loading

Keep the container, change only the content.

```tsx
function Banner() {
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(true);

  // Container always renders with fixed height
  return (
    <div className="h-24 bg-blue-500 flex items-center justify-center">
      {loading ? (
        <div className="h-6 w-48 bg-blue-400 animate-pulse rounded" />
      ) : (
        <span className="text-white font-bold">{text}</span>
      )}
    </div>
  );
}
```

## Pattern 3: Min-Height Containers

Use min-height when content height varies.

```tsx
function DynamicContent() {
  const [content, setContent] = useState(null);

  return (
    <div className="min-h-[200px]">
      {content ? <Content data={content} /> : <Skeleton />}
    </div>
  );
}
```

## Pattern 4: Aspect Ratio for Images

```tsx
function ImageCard({ src, alt }) {
  return (
    <div className="aspect-square bg-gray-200">
      <img 
        src={src} 
        alt={alt}
        className="w-full h-full object-cover"
        loading="lazy"
      />
    </div>
  );
}
```

## Anti-Patterns to Avoid

### Don't return null for loading states
```tsx
// BAD - causes layout shift
if (loading) return null;

// GOOD - reserves space
if (loading) return <Placeholder />;
```

### Don't use different layouts for loading vs loaded
```tsx
// BAD - loading text vs grid
{loading ? <p>Loading...</p> : <Grid items={items} />}

// GOOD - skeleton grid vs content grid  
{loading ? <SkeletonGrid count={6} /> : <Grid items={items} />}
```

## Key Principles

1. **Consistent dimensions**: Loading and loaded states should occupy same space
2. **Progressive enhancement**: Show structure immediately, fill in details
3. **Avoid null returns**: Always render something that reserves space
4. **Use CSS for space reservation**: min-height, aspect-ratio, explicit dimensions
